#!/usr/bin/env python3
"""Find every citation of the gap ledger by line number outside the ledger and
its history, and say what each cited line was when the citing line was written.

usage: cites.py [--json OUT]

For each citing line: the commit that last wrote it (git blame), and for each
cited line number, what that line of the ledger was at that commit and at its
parent: a row (its number) or another line (its section and its start).
"""
import json
import re
import subprocess
import sys

TREE = '/home/user/fortress'
LEDGER = 'explorations/fortress-gap-ledger.md'
ROW = re.compile(r'\|\s*(\d+)\s*\|')
CITE = re.compile(r'(?:explorations/)?fortress-gap-ledger\.md:(\d+(?:-\d+)?(?:,\s*\d+(?:-\d+)?)*)')
BARE = re.compile(r'`:(\d+(?:-\d+)?)`')
OTHER_FILE = re.compile(r'[\w./-]+\.(?:md|fss|fsi|java|scala|tex|js|py|sh|txt|out|rats|test|ast|xml)\b')


def git(*a, check=True):
    r = subprocess.run(['git', '-C', TREE] + list(a), capture_output=True, text=True)
    if check and r.returncode:
        raise SystemExit('git %s: %s' % (' '.join(a), r.stderr))
    return r.stdout


_versions = {}


def ledger_at(commit):
    if commit not in _versions:
        r = subprocess.run(['git', '-C', TREE, 'show', '%s:%s' % (commit, LEDGER)], capture_output=True, text=True)
        _versions[commit] = r.stdout.split('\n') if r.returncode == 0 else None
    return _versions[commit]


def what(lines, n):
    if lines is None or n < 1 or n > len(lines):
        return ('none', None, None)
    ln = lines[n - 1]
    m = ROW.match(ln)
    if m:
        return ('row', int(m.group(1)), None)
    sec = None
    for i in range(n - 1, -1, -1):
        if lines[i].startswith('## ') or lines[i].startswith('# '):
            sec = lines[i]
            break
    return ('other', sec, ln[:80])


def numbers(spec):
    out = []
    for part in re.split(r',\s*', spec):
        lo, _, hi = part.partition('-')
        out.append((int(lo), int(hi or lo)))
    return out


def tokens(text):
    """(start, end, spec, bare) for each ledger line citation in one line of text."""
    out = []
    last_file_is_ledger = False
    pos = 0
    events = []
    for m in CITE.finditer(text):
        events.append((m.start(), m.end(), 'cite', m.group(1)))
    for m in BARE.finditer(text):
        events.append((m.start(), m.end(), 'bare', m.group(1)))
    for m in OTHER_FILE.finditer(text):
        if 'fortress-gap-ledger' not in m.group(0):
            events.append((m.start(), m.end(), 'file', m.group(0)))
    events.sort()
    for s, e, kind, val in events:
        if kind == 'cite':
            out.append((s, e, val, False))
            last_file_is_ledger = True
        elif kind == 'file':
            if not any(s >= a and e <= b for a, b, _, _ in out):
                last_file_is_ledger = False
        elif kind == 'bare' and last_file_is_ledger:
            out.append((s, e, val, True))
    return out


def main(argv):
    grep = git('grep', '-n', 'fortress-gap-ledger.md:[0-9]', '--', ':!explorations/fortress-gap-ledger.md',
               ':!explorations/fortress-gap-ledger-history.md', check=False)
    results = []
    for g in grep.splitlines():
        path, lineno, text = g.split(':', 2)
        lineno = int(lineno)
        blame = git('blame', '--porcelain', '-L', '%d,%d' % (lineno, lineno), '--', path).split()[0]
        parent = git('rev-parse', '--verify', '--quiet', blame + '^', check=False).strip() or None
        here, before = ledger_at(blame), (ledger_at(parent) if parent else None)
        for s, e, spec, bare in tokens(text):
            cited = []
            for lo, hi in numbers(spec):
                for n in range(lo, hi + 1):
                    cited.append((n, what(here, n), what(before, n)))
            ctx = text[max(0, s - 160):s]
            ctx_rows = [int(x) for x in re.findall(r'\b[Rr]ows? (\d+)', ctx)]
            ctx_rows += [int(x) for x in re.findall(r'\b(?:and|,) (\d{1,3})\b', ctx)]
            results.append(dict(path=path, line=lineno, start=s, end=e, spec=spec, bare=bare, blame=blame[:9],
                                parent=(parent or '')[:9], cited=cited, ctx_rows=ctx_rows,
                                text=text[max(0, s - 120):e + 60]))
    if '--json' in argv:
        with open(argv[argv.index('--json') + 1], 'w') as f:
            json.dump(results, f, indent=1, default=str)
    for r in results:
        rows_here = [c[1][1] for c in r['cited'] if c[1][0] == 'row']
        rows_before = [c[2][1] for c in r['cited'] if c[2][0] == 'row']
        other = [c for c in r['cited'] if c[1][0] != 'row']
        flag = []
        if rows_here != rows_before:
            flag.append('DIFF %s' % rows_before)
        if other:
            flag.append('OTHER')
        if r['ctx_rows'] and rows_here and not set(rows_here) & set(r['ctx_rows']):
            flag.append('CTX %s' % r['ctx_rows'])
        print('%s:%d\t%s%s\t%s\t%s\t%s' % (r['path'], r['line'], ':' if r['bare'] else '', r['spec'], r['blame'],
                                         rows_here, ' '.join(flag)))


if __name__ == '__main__':
    main(sys.argv[1:])

