        events.append((m.start(), m.end(), 'cite', m.group(1)))
    for m in BARE.finditer(text):
        events.append((m.start(), m.end(), 'bare', m.group(1)))
    for m in OTHER_FILE.finditer(text):
        if 'fortress-gap-ledger' not in m.group(0):
            events.append((m.start(), m.end(), 'file', m.group(0)))
    events.sort()
    for s, e, kind, val in events:
        if kind == 'cite':
            out.append((s, e, val, False))
            last_file_is_ledger = True
        elif kind == 'file':
            if not any(s >= a and e <= b for a, b, _, _ in out):
                last_file_is_ledger = False
        elif kind == 'bare' and last_file_is_ledger:
            out.append((s, e, val, True))
    return out


def main(argv):
    grep = git('grep', '-n', 'fortress-gap-ledger.md:[0-9]', '--', ':!explorations/fortress-gap-ledger.md',
               ':!explorations/fortress-gap-ledger-history.md', check=False)
    results = []
    for g in grep.splitlines():
        path, lineno, text = g.split(':', 2)
        lineno = int(lineno)
        blame = git('blame', '--porcelain', '-L', '%d,%d' % (lineno, lineno), '--', path).split()[0]
        parent = git('rev-parse', '--verify', '--quiet', blame + '^', check=False).strip() or None
        here, before = ledger_at(blame), (ledger_at(parent) if parent else None)
        for s, e, spec, bare in tokens(text):
            cited = []
            for lo, hi in numbers(spec):
                for n in range(lo, hi + 1):
                    cited.append((n, what(here, n), what(before, n)))
            ctx = text[max(0, s - 160):s]
            ctx_rows = [int(x) for x in re.findall(r'\b[Rr]ows? (\d+)', ctx)]
            ctx_rows += [int(x) for x in re.findall(r'\b(?:and|,) (\d{1,3})\b', ctx)]
            results.append(dict(path=path, line=lineno, start=s, end=e, spec=spec, bare=bare, blame=blame[:9],
